<template>
  <q-dialog
    :model-value="modelValue"
    @update:model-value="$emit('update:modelValue', $event)"
    @hide="reset"
  >
    <q-card style="width: 520px; max-width: 90vw" data-test="mfa-settings-dialog">
      <q-toolbar class="bg-primary text-white">
        <q-toolbar-title>{{ $t('mfa_settings_title') }}</q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup data-test="mfa-settings-close" />
      </q-toolbar>

      <q-card-section v-if="loading" class="flex flex-center q-pa-lg">
        <q-spinner size="32px" color="primary" />
      </q-card-section>

      <q-banner v-if="errorMessage" class="bg-red-1 text-red-9" dense>
        {{ errorMessage }}
      </q-banner>

      <!-- STATUS -->
      <q-card-section v-if="!loading && view === 'status'">
        <template v-if="enabled">
          <div class="row items-center q-gutter-sm q-mb-md">
            <q-icon name="verified_user" color="positive" size="24px" />
            <span>{{ $t('mfa_settings_enabled') }}</span>
          </div>
          <div class="q-gutter-sm">
            <q-btn
              outline
              color="primary"
              :label="$t('mfa_settings_regenerate')"
              :disable="busy"
              data-test="mfa-regenerate-btn"
              @click="regenerate"
            />
            <q-btn
              outline
              color="negative"
              :label="$t('mfa_settings_disable')"
              :disable="busy"
              data-test="mfa-disable-btn"
              @click="view = 'disable'"
            />
          </div>
        </template>
        <template v-else>
          <p>{{ $t('mfa_settings_intro') }}</p>
          <q-btn
            unelevated
            color="primary"
            :label="$t('mfa_settings_enable')"
            :disable="busy"
            data-test="mfa-enable-btn"
            @click="startSetup"
          />
        </template>

        <!-- Email OTP: an independent second factor, enrollable on its own -->
        <q-separator class="q-my-md" />
        <div class="row items-center q-gutter-sm">
          <template v-if="emailEnabled">
            <q-icon name="mark_email_read" color="positive" size="20px" />
            <span>{{ $t('mfa_settings_email_enabled') }}</span>
          </template>
          <q-btn
            v-else
            outline
            color="primary"
            :label="$t('mfa_settings_email_enable')"
            :disable="busy"
            data-test="mfa-email-enable-btn"
            @click="startEmailSetup"
          />
        </div>

        <!-- WebAuthn / passkeys: can add several, so always offer another -->
        <template v-if="webauthnSupported">
          <q-separator class="q-my-md" />
          <q-btn
            outline
            color="primary"
            icon="fingerprint"
            :label="$t('mfa_settings_passkey_add')"
            :disable="busy"
            data-test="mfa-passkey-add-btn"
            @click="addPasskey"
          />
        </template>

        <!-- Manage passkeys + trusted devices (only meaningful once MFA is on) -->
        <template v-if="enabled">
          <q-separator class="q-my-md" />
          <q-btn
            flat
            color="primary"
            icon="settings"
            :label="$t('mfa_settings_manage')"
            :disable="busy"
            data-test="mfa-manage-btn"
            @click="openManage"
          />
        </template>
      </q-card-section>

      <!-- MANAGE: list + revoke passkeys and trusted devices -->
      <q-card-section v-if="!loading && view === 'manage'">
        <div class="text-subtitle2 q-mb-sm">{{ $t('mfa_settings_passkeys') }}</div>
        <q-list bordered separator v-if="passkeys.length" data-test="mfa-passkey-list">
          <q-item v-for="p in passkeys" :key="p.id">
            <q-item-section>
              <q-item-label>
                {{ p.name || $t('mfa_settings_passkey_unnamed') }}
                <q-popup-edit
                  :model-value="p.name || ''"
                  auto-save
                  v-slot="scope"
                  @save="(val) => renamePasskey(p, val)"
                >
                  <q-input
                    v-model="scope.value"
                    dense
                    autofocus
                    counter
                    maxlength="60"
                    @keyup.enter="scope.set"
                  />
                </q-popup-edit>
              </q-item-label>
              <q-item-label caption>{{ formatDate(p.created_on) }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <q-btn
                flat
                round
                dense
                icon="delete"
                color="negative"
                :disable="busy"
                :data-test="`mfa-passkey-delete-${p.id}`"
                @click="deletePasskey(p)"
              />
            </q-item-section>
          </q-item>
        </q-list>
        <p v-else class="text-grey">{{ $t('mfa_settings_no_passkeys') }}</p>

        <div class="text-subtitle2 q-mt-md q-mb-sm">
          {{ $t('mfa_settings_trusted_devices') }}
        </div>
        <q-list bordered separator v-if="trustedDevices.length" data-test="mfa-device-list">
          <q-item v-for="d in trustedDevices" :key="d.id">
            <q-item-section>
              <q-item-label>{{ d.user_agent || $t('mfa_settings_device_unknown') }}</q-item-label>
              <q-item-label caption>{{ formatDate(d.created_on) }}</q-item-label>
            </q-item-section>
            <q-item-section side>
              <q-btn
                flat
                round
                dense
                icon="logout"
                color="negative"
                :disable="busy"
                :data-test="`mfa-device-revoke-${d.id}`"
                @click="revokeDevice(d)"
              />
            </q-item-section>
          </q-item>
        </q-list>
        <p v-else class="text-grey">{{ $t('mfa_settings_no_devices') }}</p>

        <div class="q-mt-md q-gutter-sm">
          <q-btn
            v-if="trustedDevices.length"
            outline
            color="negative"
            :label="$t('mfa_settings_revoke_all_devices')"
            :disable="busy"
            data-test="mfa-revoke-all-btn"
            @click="revokeAllDevices"
          />
          <q-btn flat :label="$t('mfa_settings_back')" :disable="busy" @click="view = 'status'" />
        </div>
      </q-card-section>

      <!-- EMAIL OTP: confirm the emailed code -->
      <q-card-section v-if="!loading && view === 'email'">
        <p>{{ $t('mfa_settings_email_hint') }}</p>
        <q-form @submit.prevent="confirmEmail">
          <q-input
            v-model="code"
            :label="$t('mfa_challenge_code_label')"
            mask="######"
            inputmode="numeric"
            outlined
            dense
            autofocus
            :disable="busy"
            data-test="mfa-email-code"
          />
          <div class="q-mt-md q-gutter-sm">
            <q-btn
              unelevated
              type="submit"
              color="primary"
              :label="$t('mfa_challenge_submit')"
              :disable="!code || busy"
              data-test="mfa-email-confirm-btn"
            />
            <q-btn flat :label="$t('cancel')" :disable="busy" @click="view = 'status'" />
          </div>
        </q-form>
      </q-card-section>

      <!-- SETUP: QR + confirm -->
      <q-card-section v-if="!loading && view === 'setup'">
        <p>{{ $t('mfa_settings_scan_hint') }}</p>
        <div class="flex flex-center q-mb-sm">
          <img
            v-if="qrDataUri"
            :src="qrDataUri"
            alt="TOTP QR"
            style="width: 200px; height: 200px"
            data-test="mfa-qr"
          />
        </div>
        <div class="text-caption text-grey-7 q-mb-md">
          {{ $t('mfa_settings_manual_key') }}:
          <code data-test="mfa-secret">{{ secret }}</code>
        </div>
        <q-form @submit.prevent="confirmSetup">
          <q-input
            v-model="code"
            :label="$t('mfa_challenge_code_label')"
            mask="######"
            inputmode="numeric"
            outlined
            dense
            autofocus
            :disable="busy"
            data-test="mfa-confirm-code"
          />
          <div class="q-mt-md q-gutter-sm">
            <q-btn
              unelevated
              type="submit"
              color="primary"
              :label="$t('mfa_challenge_submit')"
              :disable="!code || busy"
              data-test="mfa-confirm-btn"
            />
            <q-btn flat :label="$t('cancel')" :disable="busy" @click="view = 'status'" />
          </div>
        </q-form>
      </q-card-section>

      <!-- BACKUP CODES (shown once) -->
      <q-card-section v-if="!loading && view === 'backup'">
        <div class="row items-center q-gutter-sm q-mb-sm">
          <q-icon name="check_circle" color="positive" size="22px" />
          <span>{{ $t('mfa_settings_enabled') }}</span>
        </div>
        <p class="text-weight-medium">{{ $t('mfa_settings_backup_hint') }}</p>
        <q-list bordered separator data-test="mfa-backup-codes">
          <q-item v-for="c in backupCodes" :key="c">
            <q-item-section><code>{{ c }}</code></q-item-section>
          </q-item>
        </q-list>
        <div class="q-mt-md q-gutter-sm">
          <q-btn
            outline
            color="primary"
            icon="content_copy"
            :label="$t('mfa_settings_copy')"
            @click="copyCodes"
          />
          <q-btn
            unelevated
            color="primary"
            :label="$t('mfa_settings_done')"
            data-test="mfa-backup-done"
            @click="finishBackup"
          />
        </div>
      </q-card-section>

      <!-- DISABLE: confirm with a code -->
      <q-card-section v-if="!loading && view === 'disable'">
        <p>{{ $t('mfa_settings_disable_hint') }}</p>
        <q-form @submit.prevent="disable">
          <q-input
            v-model="code"
            :label="$t('mfa_challenge_code_label')"
            outlined
            dense
            autofocus
            :disable="busy"
            data-test="mfa-disable-code"
          />
          <div class="q-mt-md q-gutter-sm">
            <q-btn
              unelevated
              type="submit"
              color="negative"
              :label="$t('mfa_settings_disable')"
              :disable="!code || busy"
              data-test="mfa-disable-confirm-btn"
            />
            <q-btn flat :label="$t('cancel')" :disable="busy" @click="view = 'status'" />
          </div>
        </q-form>
      </q-card-section>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { copyToClipboard } from 'quasar';
import { userApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import { performRegistration, isWebAuthnSupported } from 'src/utils/mfa/webauthn';
import type { dynamicObj } from 'src/pages/assets';

// DOCB-13743: TOTP enrollment + management. A self-contained dialog opened from
// the account settings. Bearer-authenticated calls via userApiService.
export default defineComponent({
  name: 'MfaSettings',
  props: {
    modelValue: { type: Boolean, default: false },
  },
  emits: ['update:modelValue'],
  data() {
    return {
      loading: false,
      busy: false,
      errorMessage: '',
      view: 'status' as 'status' | 'setup' | 'backup' | 'disable' | 'email' | 'manage',
      enabled: false,
      emailEnabled: false,
      webauthnSupported: isWebAuthnSupported(),
      qrDataUri: '',
      secret: '',
      code: '',
      backupCodes: [] as string[],
      trustedDevices: [] as Array<Record<string, string>>,
      passkeys: [] as Array<Record<string, string>>,
    };
  },
  watch: {
    modelValue(open: boolean) {
      if (open) this.loadStatus();
    },
  },
  methods: {
    reset() {
      this.view = 'status';
      this.code = '';
      this.qrDataUri = '';
      this.secret = '';
      this.backupCodes = [];
      this.errorMessage = '';
    },
    fail(err: unknown, fallbackKey = 'mfa_challenge_error') {
      // Passkey ceremony errors carry a friendly i18n code — prefer it over the
      // raw WebAuthn/w3.org DOMException text.
      const code = (err as { code?: string })?.code;
      if (code && typeof code === 'string' && code.startsWith('mfa_passkey_error_')) {
        this.errorMessage = this.$t(code) as string;
        return;
      }
      const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
      this.errorMessage = (msg as string) || (this.$t(fallbackKey) as string);
    },
    async loadStatus() {
      this.loading = true;
      this.errorMessage = '';
      try {
        const status = await userApiService.getMfaStatus();
        this.enabled = !!status?.mfa_enabled;
        this.emailEnabled = !!status?.methods?.includes('email');
        this.view = 'status';
      } catch (err) {
        this.fail(err);
      } finally {
        this.loading = false;
      }
    },
    async startEmailSetup() {
      this.busy = true;
      this.errorMessage = '';
      try {
        await userApiService.mfaEmailEnable();
        this.code = '';
        this.view = 'email';
      } catch (err) {
        this.fail(err);
      } finally {
        this.busy = false;
      }
    },
    async addPasskey() {
      this.busy = true;
      this.errorMessage = '';
      try {
        const options = await userApiService.webauthnRegisterBegin();
        const credential = await performRegistration(options);
        const res = await userApiService.webauthnRegisterComplete(credential, 'Passkey');
        this.enabled = true;
        if (res?.backup_codes?.length) {
          this.backupCodes = res.backup_codes;
          this.view = 'backup';
        } else {
          await this.loadStatus();
        }
      } catch (err) {
        this.fail(err);
      } finally {
        this.busy = false;
      }
    },
    async confirmEmail() {
      if (!this.code) return;
      this.busy = true;
      this.errorMessage = '';
      try {
        const res = await userApiService.mfaEmailConfirm(this.code.trim());
        this.emailEnabled = true;
        this.enabled = true;
        this.code = '';
        // Backup codes come back only when this was the first factor.
        if (res?.backup_codes?.length) {
          this.backupCodes = res.backup_codes;
          this.view = 'backup';
        } else {
          this.view = 'status';
        }
      } catch (err) {
        this.fail(err);
      } finally {
        this.busy = false;
      }
    },
    async startSetup() {
      this.busy = true;
      this.errorMessage = '';
      try {
        const setup = await userApiService.mfaTotpSetup();
        this.qrDataUri = setup?.qr_data_uri || '';
        this.secret = setup?.secret || '';
        this.code = '';
        this.view = 'setup';
      } catch (err) {
        this.fail(err);
      } finally {
        this.busy = false;
      }
    },
    async confirmSetup() {
      if (!this.code) return;
      this.busy = true;
      this.errorMessage = '';
      try {
        const res = await userApiService.mfaTotpConfirm(this.code.trim());
        this.backupCodes = res?.backup_codes || [];
        this.enabled = true;
        this.code = '';
        this.view = 'backup';
      } catch (err) {
        this.fail(err);
      } finally {
        this.busy = false;
      }
    },
    async regenerate() {
      this.busy = true;
      this.errorMessage = '';
      try {
        const res = await userApiService.mfaRegenerateBackupCodes();
        this.backupCodes = res?.backup_codes || [];
        this.view = 'backup';
      } catch (err) {
        this.fail(err);
      } finally {
        this.busy = false;
      }
    },
    async disable() {
      if (!this.code) return;
      this.busy = true;
      this.errorMessage = '';
      try {
        await userApiService.mfaDisable(this.code.trim());
        this.enabled = false;
        this.code = '';
        this.view = 'status';
      } catch (err) {
        this.fail(err);
      } finally {
        this.busy = false;
      }
    },
    finishBackup() {
      this.backupCodes = [];
      this.view = 'status';
    },
    formatDate(iso?: string) {
      if (!iso) return '';
      const d = new Date(iso);
      return isNaN(d.getTime()) ? '' : d.toLocaleString();
    },
    async openManage() {
      this.busy = true;
      this.errorMessage = '';
      try {
        const [devices, creds] = await Promise.all([
          userApiService.listTrustedDevices(),
          userApiService.listPasskeys(),
        ]);
        this.trustedDevices = devices?.devices || [];
        this.passkeys = creds?.credentials || [];
        this.view = 'manage';
      } catch (err) {
        this.fail(err);
      } finally {
        this.busy = false;
      }
    },
    async renamePasskey(p: Record<string, string>, name: string) {
      const clean = (name || '').trim();
      if (!clean || clean === p.name) return;
      this.busy = true;
      this.errorMessage = '';
      try {
        await userApiService.renamePasskey(p.id, clean);
        p.name = clean;
      } catch (err) {
        this.fail(err);
      } finally {
        this.busy = false;
      }
    },
    async deletePasskey(p: Record<string, string>) {
      this.busy = true;
      this.errorMessage = '';
      try {
        await userApiService.deletePasskey(p.id);
        this.passkeys = this.passkeys.filter((x) => x.id !== p.id);
        // Deleting the last factor turns MFA off server-side — resync.
        await this.loadStatus();
        if (this.enabled) this.view = 'manage';
      } catch (err) {
        this.fail(err);
      } finally {
        this.busy = false;
      }
    },
    async revokeDevice(d: Record<string, string>) {
      this.busy = true;
      this.errorMessage = '';
      try {
        await userApiService.revokeTrustedDevice(d.id);
        this.trustedDevices = this.trustedDevices.filter((x) => x.id !== d.id);
      } catch (err) {
        this.fail(err);
      } finally {
        this.busy = false;
      }
    },
    async revokeAllDevices() {
      this.busy = true;
      this.errorMessage = '';
      try {
        await userApiService.revokeAllTrustedDevices();
        this.trustedDevices = [];
      } catch (err) {
        this.fail(err);
      } finally {
        this.busy = false;
      }
    },
    async copyCodes() {
      try {
        await copyToClipboard(this.backupCodes.join('\n'));
      } catch {
        /* clipboard denied — user can select manually */
      }
    },
  },
});
</script>
