<template>
  <q-item
    clickable
    @click="toggleDarkMode()"
    v-ripple
    id="dark_mode_box"
    data-test="dark-mode-toggle"
  >
    <q-item-section avatar>
      <q-icon
        v-if="!darkMode"
        class="icon-grey"
        name="dark_mode"
        id="dark_mode_icon"
        data-test="dark-mode-icon"
      />
      <q-icon
        v-if="darkMode"
        class="icon-grey"
        name="light_mode"
        id="dark_mode_icon"
        data-test="light-mode-icon"
      />
    </q-item-section>
    <q-item-section v-if="!darkMode" id="dark_mode_text" data-test="dark-mode-text">
      {{ $t('dark_mode') }}
    </q-item-section>
    <q-item-section v-if="darkMode" id="dark_mode_text" data-test="light-mode-text">
      {{ $t('light_mode') }}
    </q-item-section>
  </q-item>
  <!-- <label for="Dark Mode">Dark Mode</label>

  <f-toggle size="xs"
    v-model="darkMode"
    checked-icon="dark_mode"
    @update:model-value="(val)=> {}"
    unchecked-icon="light_mode"
  /> -->

  <q-inner-loading :showing="loading || loading_settings">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { Dark } from 'quasar';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { dark_mode_setting } from 'src/constants';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
    props: [],
  components: {},
  mounted() {
    const response = Dark.isActive;
    if (Boolean(response) == true) {
      this.darkMode = true;
    } else {
      this.darkMode = false;
    }
  },
  data() {
    return {
      darkMode: false,
      dark_mode_setting,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (
          newVal == false &&
          oldVal == true &&
          !this.user_settings[this.dark_mode_setting]
        ) {
          this.user_settings[this.dark_mode_setting] = false;
        }
      },
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { setUserPreferences } = settings_store;
    return {
      setUserPreferences,
      user_settings,
      loading_settings,
      settings_store,
      loading: ref(false),
    };
  },
  methods: {
    toggleDarkMode() {
      this.$q.dark.toggle();
      this.darkMode = !this.darkMode;
      this.setUserPreferences(this.dark_mode_setting, this.darkMode);
    },
  },
});
</script>

<style lang="scss" scoped></style>
